// The cadence maths. For each lead: days between last_touch and now, compared against the
// grade's interval. A WARM lead touched 10 days ago is overdue (5-day cadence); one touched
// yesterday is not.
const cfg = $('Config').first().json;
const CADENCE = {
  HOT: Number(cfg.CADENCE_HOT_DAYS),
  WARM: Number(cfg.CADENCE_WARM_DAYS),
  COLD: Number(cfg.CADENCE_COLD_DAYS),
  JUNK: 999
};
const MAX_FOLLOWUPS = Number(cfg.MAX_FOLLOWUPS);
const HOLD_HOURS = Number(cfg.CONVERSATION_HOLD_HOURS);
const CAP = Number(cfg.DAILY_SEND_CAP);
const STOPPED = ['Booked', 'Lost', 'Dropped'];
const now = Date.now();
const ms = (v) => new Date(v || 0).getTime() || 0;

const due = [];
const skipped = { stopped: 0, in_conversation: 0, capped: 0, not_due: 0, no_whatsapp: 0, junk: 0 };

for (const l of $input.all().map(i => i.json)) {
  const status = String(l.status || 'New').trim();

  // 1. Finished leads are never touched again.
  if (STOPPED.includes(status)) { skipped.stopped++; continue; }

  // 2. Never talk over a live conversation. RE-00 sets status Engaged the moment a buyer
  //    replies, so a scheduled follow-up would otherwise land on top of a live chat.
  //    Once they have gone quiet for HOLD_HOURS the conversation is over and nurture resumes.
  if (status === 'Engaged') {
    const quietHours = (now - ms(l.last_inbound_at || l.last_touch)) / 3600000;
    if (quietHours < HOLD_HOURS) { skipped.in_conversation++; continue; }
  }

  // 3. The hard stop. followup_count counts AUTOMATED follow-ups only - not button taps -
  //    so an engaged buyer who taps six buttons is not silently locked out of nurture.
  const sent = Number(l.followup_count || 0);
  if (sent >= MAX_FOLLOWUPS) { skipped.capped++; continue; }

  // 4. Cadence by grade.
  const grade = String(l.grade || 'WARM').toUpperCase();
  if (grade === 'JUNK') { skipped.junk++; continue; }
  const interval = CADENCE[grade] ?? CADENCE.WARM;
  const days = (now - ms(l.last_touch || l.created_at)) / 86400000;
  if (days < interval) { skipped.not_due++; continue; }

  const wa = String(l.wa_id || '').replace(/\D/g, '');
  if (wa.length < 11) { skipped.no_whatsapp++; continue; }

  due.push({
    ...l,
    wa_id: wa,
    grade,
    cadence_days: interval,
    days_since_touch: Math.floor(days),
    followup_number: sent + 1,
    max_followups: MAX_FOLLOWUPS,
    resumed_after_conversation: status === 'Engaged'
  });
}

// Oldest contact first, so nobody starves if the daily cap bites.
due.sort((a, b) => b.days_since_touch - a.days_since_touch);
const send = due.slice(0, CAP);
skipped.over_daily_cap = due.length - send.length;
return send.map(l => ({ json: { ...l, sweep: { due: due.length, sending: send.length, skipped } } }));

// WhatsApp template variables cannot contain newlines, tabs or 4+ consecutive spaces, and
// Meta rejects the whole send if they do. Sanitise here rather than trusting the model.
const lead = $('Find Follow-Ups Due').all()[$itemIndex].json;
const blocks = Array.isArray($json.content) ? $json.content : [];
const text = blocks.filter(b => b.type === 'text').map(b => b.text).join('').trim();
let ai = null;
if ($json.stop_reason !== 'refusal' && text) { try { ai = JSON.parse(text); } catch (e) { ai = null; } }

const clean = (s) => String(s || '')
  .replace(/[\r\n\t]+/g, ' ')
  .replace(/\s{4,}/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 240)
  .trim();

let line = clean(ai && ai.update_line);
let fallback = false;
if (line.length < 15) {
  // Never send an empty variable - Meta would reject it and the touch would be wasted.
  line = clean('a few units in your configuration are still open this month. Want me to send the current availability and payment plan?');
  fallback = true;
}
return { json: {
  ...lead,
  update_line: line,
  internal_note: clean(ai && ai.internal_note) || (fallback ? 'Generic line used - model output unusable' : ''),
  used_fallback_copy: fallback
} };

